#!/bin/sh
# Regenerates gdal_reference.json: an independent GDAL reference for the
# HiRISE A02 pixel convention. Manual tool only; go test never runs it.
#
# Requires: docker, python3, network access to hirise-pds.lpl.arizona.edu.
# GDAL reads the product with HTTP Range requests (/vsicurl/); nothing is
# downloaded in full. Usage, from this directory:
#
#   sh gdal_reference.sh > gdal_reference.json
set -eu

IMAGE=ghcr.io/osgeo/gdal@sha256:7125d6f5d6af5331354328fc6a64c9e420b29b31460d1a6aaf9526e559255e07 # ubuntu-small-3.9.3
URL=https://hirise-pds.lpl.arizona.edu/PDS/DTM/ESP/ORB_029700_029799/ESP_029716_1980_ESP_029426_1980/DTEED_029716_1980_029426_1980_A02.IMG
SRS="+proj=longlat +R=3394839.8133163 +no_defs"
WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

# Probe list in GDAL pixel/line coordinates (0,0 = outer NW corner of pixel
# (0,0); pixel centres at +0.5): the corner and centre of 9 pixels (the four
# raster corners and 5 interior pixels), plus centre offsets of +-0.25,
# +-0.49 and +-1 pixel on each axis around two interior pixels.
python3 -I - "$WORK" <<'EOF'
import json, sys
work = sys.argv[1]
probes = [(0, 0), (3503, 0), (0, 8251), (3503, 8251), (1752, 4126), (1000, 2000), (2500, 6000), (1200, 7000), (2300, 1500)]
rows = []
for p, l in probes:
    rows.append(("corner", p, l, 0, 0, p, l))
    rows.append(("centre", p, l, 0, 0, p + 0.5, l + 0.5))
for p, l in [(1752, 4126), (1000, 2000)]:
    for d in (-1, -0.49, -0.25, 0.25, 0.49, 1):
        rows.append(("offset", p, l, d, 0, p + 0.5 + d, l + 0.5))
        rows.append(("offset", p, l, 0, d, p + 0.5, l + 0.5 + d))
json.dump(rows, open(f"{work}/rows.json", "w"))
open(f"{work}/pixels.txt", "w").write("".join(f"{r[5]!r} {r[6]!r}\n" for r in rows))
EOF

docker run --rm "$IMAGE" gdalinfo --version > "$WORK/version.txt"
docker run --rm "$IMAGE" gdalinfo -json "/vsicurl/$URL" > "$WORK/gdalinfo.json"
docker run -i --rm "$IMAGE" gdaltransform -t_srs "$SRS" -output_xy "/vsicurl/$URL" < "$WORK/pixels.txt" > "$WORK/transform.txt"
python3 -I - "$WORK" <<'EOF'
import json, sys
work = sys.argv[1]
rows = json.load(open(f"{work}/rows.json"))
lonlat = open(f"{work}/transform.txt").read().split("\n")
open(f"{work}/probe.txt", "w").write("".join(lonlat[i] + "\n" for i, r in enumerate(rows) if r[0] != "corner"))
EOF
docker run -i --rm "$IMAGE" gdallocationinfo -xml -l_srs "$SRS" "/vsicurl/$URL" < "$WORK/probe.txt" > "$WORK/locations.xml"

python3 -I - "$WORK" "$IMAGE" "$URL" "$SRS" <<'EOF'
import datetime, hashlib, json, sys, xml.etree.ElementTree as ET
work, image, url, srs = sys.argv[1:5]
info = json.load(open(f"{work}/gdalinfo.json"))
rows = json.load(open(f"{work}/rows.json"))
lonlat = [l.split() for l in open(f"{work}/transform.txt").read().strip().split("\n")]
reports = ET.fromstring("<r>" + open(f"{work}/locations.xml").read() + "</r>").findall("Report")
label = open("DTEED_029716_1980_029426_1980_A02.LBL", "rb").read()
transforms, locations = [], []
probe = iter(reports)
for r, (lon, lat) in zip(rows, lonlat):
    transforms.append({"kind": r[0], "pixel": r[1], "line": r[2], "dPixel": r[3], "dLine": r[4],
                       "gdalPixel": r[5], "gdalLine": r[6], "lon": float(lon), "lat": float(lat)})
    if r[0] == "corner":
        continue
    rep = next(probe)
    locations.append({"pixel": r[1], "line": r[2], "dPixel": r[3], "dLine": r[4], "lon": float(lon), "lat": float(lat),
                      "reportedPixel": int(rep.get("pixel")), "reportedLine": int(rep.get("line")),
                      "value": rep.find("BandReport/Value").text})
crs = info["coordinateSystem"]["wkt"]
out = {
    "purpose": "Independent GDAL reference for the A02 pixel convention (docs/MARSGEO.md). Generated by gdal_reference.sh; do not edit.",
    "generated": datetime.date.today().isoformat(),
    "gdalImage": image,
    "gdalVersion": open(f"{work}/version.txt").read().strip(),
    "configOptions": "defaults (none set)",
    "source": url,
    "labelFile": "DTEED_029716_1980_029426_1980_A02.LBL",
    "labelSha256": hashlib.sha256(label).hexdigest(),
    "commands": [
        "gdalinfo -json /vsicurl/<source>",
        f"gdaltransform -t_srs '{srs}' -output_xy /vsicurl/<source>  (stdin: gdalPixel gdalLine)",
        f"gdallocationinfo -xml -l_srs '{srs}' /vsicurl/<source>  (stdin: lon lat)",
    ],
    "pixelConvention": "GDAL pixel/line: (0,0) is the outer north-west corner of pixel (0,0); pixel centres at +0.5.",
    "size": info["size"],
    "geoTransform": info["geoTransform"],
    "noDataValue": info["bands"][0].get("noDataValue"),
    "srsWkt": crs,
    "transforms": transforms,
    "locations": locations,
}
json.dump(out, sys.stdout, indent=1)
print()
EOF
